+
+function dateOnly(value) {
+  const d = new Date(value);
+  if (Number.isNaN(d.getTime())) return null;
+  return d;
+}
+
+function calculatePricing(property, nights) {
+  const base = property.price.basePrice * nights;
+  const cleaning = property.price.cleaningFee || 0;
+  const taxes = (base + cleaning) * (property.price.taxRate || 0);
+  const total = base + cleaning + taxes;
+  return {
+    currency: property.price.currency,
+    nights,
+    basePrice: base,
+    cleaningFee: cleaning,
+    taxes: Math.round(taxes * 100) / 100,
+    totalPrice: Math.round(total * 100) / 100,
+  };
+}
+
+async function isAvailable(propertyId, checkIn, checkOut) {
+  // Overlap rule: [a,b) overlaps [c,d) if a < d AND c < b
+  const overlapping = await Booking.findOne({
+    property: propertyId,
+    status: { $in: ['pending', 'confirmed'] },
+    checkIn: { $lt: checkOut },
+    checkOut: { $gt: checkIn },
+  }).select('_id');
+  return !overlapping;
+}
+
