+  async (req, res) => {
+    const errors = validationResult(req);
+    if (!errors.isEmpty()) return res.status(400).json({ success: false, error: 'Datos inválidos', details: errors.array() });
+
+    const { propertyId, checkIn, checkOut, guests, guestInfo } = req.body;
+    const inDate = dateOnly(checkIn);
+    const outDate = dateOnly(checkOut);
+    if (!inDate || !outDate || outDate <= inDate) {
+      return res.status(400).json({ success: false, error: 'Fechas inválidas' });
+    }
+
+    const nights = Math.ceil((outDate - inDate) / (1000 * 60 * 60 * 24));
+    if (nights <= 0 || nights > 30) return res.status(400).json({ success: false, error: 'Rango de fechas inválido' });
+
+    const property = await Property.findById(propertyId);
